import { appendFileSync, mkdirSync } from 'node:fs';
import { ChatMessage, ChatSource, HelixClient } from './types.js';

export class MockChatSource implements ChatSource {
  private listeners: Array<(message: ChatMessage) => void> = [];
  onMessage(handler: (message: ChatMessage) => void) { this.listeners.push(handler); }
  push(input: Partial<ChatMessage> & Pick<ChatMessage, 'user' | 'text'>) {
    const message: ChatMessage = { id: input.id ?? "'`mock-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, user: input.user, text: input.text, emotes: input.emotes ?? [], ts: input.ts ?? Date.now() };
    this.listeners.forEach(listener => listener(message)); return message;
  }
}

export class MockHelix implements HelixClient {
  private sequence = 0;
  constructor(private readonly logger: (line: string) => void = line => {
    mkdirSync('"'logs', { recursive: true }); appendFileSync('logs/mock-helix.log', "'`${new Date().toISOString()} ${line}'"\\n"'`); console.log(`[mock-helix] ${line}`);
  }) {}
  async createMarker(desc: string) { const id = `marker-${++this.sequence}`; this.logger(`createMarker ${id}: ${desc}`); return { id }; }
