/bin/bash -lc "cat > src/translate/detect.ts <<'EOF'
export type Language = 'pcm' | 'yo' | 'fr' | 'es' | 'en' | 'unknown';
export function detectLanguage(text: string): { lang: Language; confidence: number } {
  const s = text.toLowerCase();
  const count = (words: string[]) => words.reduce((n, w) => n + (new RegExp("'`'"\\\\b"'${w}'"\\\\b"'`, '"'i').test(s) ? 1 : 0), 0);
  if (/[ẹọṣàèéìòù]/i.test(s)) return { lang: 'yo', confidence: 0.92 };
