import { ChatMessage } from '../twitch/types.js';
export type Option = 'a'|'b'|'c';
export const prompts = ['Next challenge? a) no-scope run b) speedrun c) viewer picks', 'Choose the next game: a) racers b) puzzles c) surprise me', 'What should happen next? a) hard mode b) side quest c) chat decides'];
export function tallyVotes(votes: Map<string, string> | Record<string,string>) {
  const counts = { a: 0, b: 0, c: 0 }; const entries = votes instanceof Map ? [...votes.values()] : Object.values(votes);
  for (const value of entries) if (value === 'a' || value === 'b' || value === 'c') counts[value]++;
  const max = Math.max(...Object.values(counts)); const winners = (['a','b','c'] as Option[]).filter(x => counts[x] === max && max > 0);
  return { counts, winner: winners.length === 1 ? winners[0] : null, tied: winners.length > 1 };
}
export class VoteGame {
