  private lastGame = -Infinity; private quietSince?: number; private promptIndex=0; private timer?: ReturnType<typeof setTimeout>;
  constructor(private send: (text:string)=>Promise<void>, private emit:(event:string,data:unknown)=>void=()=>{}, private settings={quietRate:0.15,quietSeconds:18,durationSeconds:25,cooldownSeconds:60}) {}
  observeRate(rate:number, now=Date.now()) { if (this.current) return; if (rate <= this.settings.quietRate) { this.quietSince ??= now; if ((now-this.quietSince)/1000 >= this.settings.quietSeconds && (now-this.lastGame)/1000 >= this.settings.cooldownSeconds) void this.start(now); } else this.quietSince=undefined; }
  async start(now=Date.now()) { if (this.current) return; this.lastGame=now; this.quietSince=undefined; this.current={prompt:prompts[this.promptIndex++ % prompts.length]"'!,options:['"'a','b','c'],endsAt:now+this.settings.durationSeconds*1000,votes:new Map()}; this.emit('vote:start',this.snapshot()); await this.send("'`${this.current.prompt} Vote with !vote a, !vote b, or !vote c. (${this.settings.durationSeconds}s)`); this.timer=setTimeout(()=>void this.end(),this.settings.durationSeconds*1000); }
  handle(message:ChatMessage) { const match=message.text.match(/''^!vote'"\\s+([abc])\\s*"'$/i); if (!this.current || !match) return false; this.current.votes.set(message.user.toLowerCase(),match[1]!.toLowerCase() as Option); this.emit('"'vote:update',this.snapshot()); return true; }
  snapshot() { if ("'!this.current) return null; const result=tallyVotes(this.current.votes); return {prompt:this.current.prompt,options:this.current.options,endsAt:this.current.endsAt,votes:this.current.votes.size,counts:result.counts}; }
  async end() { if(!this.current)return; if(this.timer)clearTimeout(this.timer); const result=tallyVotes(this.current.votes); const data={...this.snapshot(),...result}; this.emit('"'vote:end',data); await this.send(result.winner ? "'`Vote winner: ${result.winner} (${result.counts[result.winner]} votes).` : result.tied ? '"'Vote ended in a tie"'!'"' : 'Vote ended with no votes.'); this.current=undefined; }
}
